class Solution { public int findTheCity(int n,int[][] e,int t) { int inf=1000000000;int[][] d=new int[n][n];for(int i=0;i<n;i++){Arrays.fill(d[i],inf);d[i][i]=0;}for(int[] x:e){d[x[0]][x[1]]=x[2];d[x[1]][x[0]]=x[2];}for(int k=0;k<n;k++)for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(d[i][k]<inf&&d[k][j]<inf)d[i][j]=Math.min(d[i][j],d[i][k]+d[k][j]);int best=-1,min=Integer.MAX_VALUE;for(int i=0;i<n;i++){int c=0;for(int j=0;j<n;j++)if(i!=j&&d[i][j]<=t)c++;if(c<=min){min=c;best=i;}}return best;} }
